export default {
  fetch: async (req, env, ctx) => {
    try {
      return await handleRequest(req, env, ctx);
    } catch (err) {
      console.error('Worker error:', err);
      return json({ error: err.message || '服务器内部错误' }, 500);
    }
  }
};
